set -euo pipefail

experiment_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
repo_root="$(cd -- "${experiment_dir}/../../../../.." && pwd)"
cd "${repo_root}"
output_dir="${PAGE_TEXT_RESULTS_DIR:-${experiment_dir}/results}"
mkdir -p "${output_dir}"
runner=(bash scripts/run-single-benchmark.sh --module core/sail/lmdb --no-build)
jmh=(--warmup-iterations 3 --measurement-iterations 5 --forks 1)

case "${1:-help}" in
  prepare)
    # Dependencies must already be available offline; omit -o once if resolution is necessary.
    mvn -o -B -ntp -Dmaven.repo.local=.m2_repo -Pquick clean install
    mvn -o -B -ntp -Dmaven.repo.local=.m2_repo -pl core/sail/lmdb \
      -Dtest=PageTextPrototypeSummaryTest,PageTextPrototypePagesTest,PageTextPrototypeResourceCorpusTest,PageTextPrototypeScanTest \
      -DskipITs -Djapicmp.skip=true verify
    mvn -o -B -ntp -Dmaven.repo.local=.m2_repo -pl core/sail/lmdb -Pbenchmarks,quick package
    ;;
  census)
    "${runner[@]}" --main-class org.eclipse.rdf4j.sail.lmdb.PageTextPrototypeCensus \
      --jvm-arg -Xms1g --jvm-arg -Xmx3g \
      --main-arg "${output_dir}/census.csv" --main-arg "${2:-32768}" \
      > "${output_dir}/census.log" 2>&1
    ;;
  scans)
    scenario_file="${2:-${experiment_dir}/scan-scenarios.txt}"
    scenarios="$(python3 - "${scenario_file}" <<'PY'
import pathlib, sys
print(','.join(line.strip() for line in pathlib.Path(sys.argv[1]).read_text().splitlines()
               if line.strip() and not line.lstrip().startswith('#')))
PY
)"
    "${runner[@]}" --class org.eclipse.rdf4j.sail.lmdb.PageTextPrototypeBenchmark --method scan \
      "${jmh[@]}" --param "scenario=${scenarios}" --param "size=${PAGE_TEXT_SCAN_SIZE:-131072}" \
      --param "pipeline=NONE,LITERAL_ONLY,PAGE_ONLY,PAGE_AND_LITERAL" \
      --jmh-arg -rf --jmh-arg json --jmh-arg -rff --jmh-arg "${output_dir}/scans.json" \
      > "${output_dir}/scans.log" 2>&1
    ;;
  construction)
    "${runner[@]}" --class org.eclipse.rdf4j.sail.lmdb.PageTextPrototypeBuildBenchmark --method build \
      "${jmh[@]}" --param corpus=CATALOG --param size=32768 --param entriesPerPage=16,1024 \
      --param variant=COMMON32,GRAM256,GRAM1024,GRAM4096,FOURGRAM4096,EQ_HASH4096,PREFIX_GRAM1024 \
      --param mode=NORMALIZED,NORMALIZE \
      --jmh-arg -rf --jmh-arg json --jmh-arg -rff --jmh-arg "${output_dir}/construction.json" \
      > "${output_dir}/construction.log" 2>&1
    "${runner[@]}" --class org.eclipse.rdf4j.sail.lmdb.PageTextPrototypeBuildBenchmark --method build \
      "${jmh[@]}" --param corpus=CATALOG --param size=32768 --param entriesPerPage=16,1024 \
      --param variant=GRAM256 --param mode=OR_EXISTING \
      --jmh-arg -rf --jmh-arg json --jmh-arg -rff --jmh-arg "${output_dir}/construction-or.json" \
      > "${output_dir}/construction-or.log" 2>&1
    ;;
  *)
    printf '%s\n' 'Usage: run-experiment.sh prepare|census [size]|scans [scenario-file]|construction'
    ;;
esac
